import { Check, Minus } from 'lucide-react'
import { useEffect, useId, useRef, useState, type ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './checkbox.module.scss'

export interface CheckboxProps {
  checked?: boolean
  defaultChecked?: boolean
  indeterminate?: boolean
  onChange?: (checked: boolean) => void
  onCheckedChange?: (checked: boolean) => void
  disabled?: boolean
  label?: ReactNode
  hint?: string
  error?: string
  required?: boolean
  id?: string
  name?: string
  /** Applied to the outer wrapper. */
  className?: string
  /** Applied to the native input (e.g. table cells). */
  inputClassName?: string
  'aria-label'?: string
}

/**
 * Accessible checkbox — GuardCore API (`onChange`, `indeterminate`, `label`)
 * plus shadcn-style `onCheckedChange`.
 */
export function Checkbox({
  checked: checkedProp,
  defaultChecked = false,
  indeterminate = false,
  onChange,
  onCheckedChange,
  disabled,
  label,
  hint,
  error,
  required,
  id: idProp,
  name,
  className,
  inputClassName,
  'aria-label': ariaLabel,
}: CheckboxProps) {
  const generatedId = useId()
  const id = idProp ?? generatedId
  const inputRef = useRef<HTMLInputElement>(null)
  const [uncontrolled, setUncontrolled] = useState(defaultChecked)
  const checked = checkedProp ?? uncontrolled

  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.indeterminate = indeterminate
    }
  }, [indeterminate])

  const notify = (next: boolean) => {
    if (checkedProp === undefined) setUncontrolled(next)
    onChange?.(next)
    onCheckedChange?.(next)
  }

  return (
    <div className={cx(styles.field, className)}>
      <label
        className={cx(styles.row, disabled && styles.rowDisabled)}
        data-disabled={disabled ? 'true' : undefined}
      >
        <span className={styles.controlWrap}>
          <input
            ref={inputRef}
            type="checkbox"
            id={id}
            name={name}
            checked={checked}
            disabled={disabled}
            required={required}
            aria-label={ariaLabel}
            aria-checked={indeterminate ? 'mixed' : checked}
            aria-invalid={error ? true : undefined}
            aria-describedby={
              error ? `${id}-error` : hint ? `${id}-hint` : undefined
            }
            onChange={(event) => notify(event.currentTarget.checked)}
            className={cx(styles.control, inputClassName)}
          />
          <span className={styles.box} aria-hidden>
            <Check className={styles.check} />
            <Minus className={styles.dash} />
          </span>
        </span>

        {label ? (
          <span className={styles.label}>
            {label}
            {required ? (
              <span className={styles.required} aria-hidden>
                *
              </span>
            ) : null}
          </span>
        ) : null}
      </label>

      {hint && !error ? (
        <p id={`${id}-hint`} className={styles.hint}>
          {hint}
        </p>
      ) : null}

      {error ? (
        <p id={`${id}-error`} role="alert" className={styles.error}>
          {error}
        </p>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.field {
  display: flex;
  flex-direction: column;
  gap: vz.space(0.5);
  min-width: 0;
}

.row {
  display: inline-flex;
  align-items: flex-start;
  gap: vz.space(2.5);
  cursor: pointer;
  user-select: none;
}

.row-disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.control-wrap {
  position: relative;
  display: inline-flex;
  flex: none;
  width: 1.125rem;
  height: 1.125rem;
  margin-top: 0.0625rem;
}

.control {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  opacity: 0;
  cursor: inherit;
}

.box {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border: 1px solid vz.color('input');
  border-radius: vz.radius('xs');
  background: vz.color('card');
  color: transparent;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    border-color vz.duration('fast') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.control:checked + .box,
.control:indeterminate + .box {
  border-color: vz.color('primary');
  background: vz.color('primary');
  color: vz.color('primary-foreground');
}

.control:focus-visible + .box {
  outline: 2px solid vz.color('ring', 0.6);
  outline-offset: 2px;
}

.check,
.dash {
  position: absolute;
  inset: 0;
  display: block;
  width: 0.625rem;
  height: 0.625rem;
  margin: auto;
  opacity: 0;
  stroke-width: 3.5;
  transition: opacity vz.duration('fast') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.control:checked + .box .check {
  opacity: 1;
}

.control:indeterminate + .box .check {
  opacity: 0;
}

.control:indeterminate + .box .dash {
  opacity: 1;
}

.label {
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  line-height: 1.35;
}

.required {
  margin-left: vz.space(1);
  color: vz.color('destructive');
}

.hint,
.error {
  margin: 0;
  margin-left: calc(1.125rem + #{vz.space(2.5)});
  font-size: vz.font-size('xs');
  line-height: 1.45;
}

.hint {
  color: vz.color('muted-foreground');
}

.error {
  color: vz.color('destructive');
}
